WITH uk AS (
  SELECT Population, Continent, LifeExpectancy FROM country WHERE Code = 'GBR'
),
total_qual AS (
  SELECT SUM(Population) AS total_pop FROM country WHERE Continent = 'Europe' AND LifeExpectancy > 75
)
SELECT ROUND(
  CASE WHEN uk.Continent = 'Europe' AND uk.LifeExpectancy > 75
       THEN uk.Population * (103000.0 / total_qual.total_pop) * 1.004
       ELSE uk.Population * 1.004
  END
) AS pop_one_year_later
FROM uk, total_qual;
